// Import necessary modules
const express = require('express');
const bodyParser = require('body-parser');
const cors = require('cors');

// Initialize app
const app = express();
const PORT = 3000;

// Enable CORS for all origins
app.use(cors());

// In-memory store to hold todos
let todos = [];

// Middleware to parse JSON bodies
app.use(bodyParser.json());

// Function to validate todo object
function isValidTodo(todo) {
  const titleValidation = typeof todo.title === 'string' && todo.title.length >= 1 && todo.title.length <= 100;
  return titleValidation;
}

// List all todos
app.get('/todos', (req, res) => {
  let filteredTodos = todos;

  if (req.query.completed !== undefined) {
    const isCompleted = req.query.completed === 'true';
    filteredTodos = todos.filter(todo => todo.completed === isCompleted);
  }

  res.json(filteredTodos);
});

// Get single todo
app.get('/todos/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  const todo = todos.find(t => t.id === id);

  if (!todo) {
    return res.status(404).json({ message: 'Todo not found' });
  }

  res.json(todo);
});

// Create new todo
app.post('/todos', (req, res) => {
  const { title } = req.body;

  if (!title || !isValidTodo(req.body)) {
    return res.status(400).json({ message: 'Invalid title or missing title' });
  }

  const newTodo = {
    id: todos.length + 1,
    title,
    completed: false,
    createdAt: Date.now(),
    updatedAt: Date.now()
  };

  todos.push(newTodo);
  res.status(201).json(newTodo);
});

// Update todo
app.put('/todos/:id', (req, res) => {
  const { id } = req.params;
  const { title, completed } = req.body;

  if (!isValidTodo(req.body)) {
    return res.status(400).json({ message: 'Invalid title or missing title' });
  }

  const todoIndex = todos.findIndex(t => t.id === parseInt(id, 10));

  if (todoIndex === -1) {
    return res.status(404).json({ message: 'Todo not found' });
  }

  todos[todoIndex] = {
    ...todos[todoIndex],
    title,
    completed,
    updatedAt: Date.now()
  };

  res.json(todos[todoIndex]);
});

// Delete todo
app.delete('/todos/:id', (req, res) => {
  const { id } = req.params;

  const todoIndex = todos.findIndex(t => t.id === parseInt(id, 10));

  if (todoIndex === -1) {
    return res.status(404).json({ message: 'Todo not found' });
  }

  todos.splice(todoIndex, 1);
  res.json({ message: 'Todo deleted' });
});

// Export the app for testing
module.exports = app;
