// Import necessary modules
const supertest = require('supertest');
const app = require('./app'); // Adjust path as needed

describe('Todo List API', () => {
  beforeEach(() => {
    todos = [];
  });

  it('should list all todos', async () => {
    await supertest(app)
      .get('/todos')
      .expect(200)
      .expect([]);
  });

  it('should get single todo by ID', async () => {
    const newTodo = { title: 'Test Todo' };
    await supertest(app)
      .post('/todos')
      .send(newTodo)
      .expect(201);

    const response = await supertest(app)
      .get(`/todos/${newTodo.id}`)
      .expect(200);
    expect(response.body.title).toBe('Test Todo');
  });

  it('should create a new todo', async () => {
    const newTodo = { title: 'New Test Todo' };
    const response = await supertest(app)
      .post('/todos')
      .send(newTodo)
      .expect(201);

    expect(response.body.title).toBe('New Test Todo');
  });

  it('should update an existing todo', async () => {
    const newTodo = { title: 'Updated Test Todo' };
    await supertest(app)
      .post('/todos')
      .send(newTodo)
      .expect(201);

    const updatedTodo = { title: 'New Updated Test Todo', completed: true };
    const response = await supertest(app)
      .put(`/todos/${newTodo.id}`)
      .send(updatedTodo)
      .expect(200);
    expect(response.body.title).toBe('New Updated Test Todo');
    expect(response.body.completed).toBe(true);
  });

  it('should delete a todo', async () => {
    const newTodo = { title: 'Delete Test Todo' };
    await supertest(app)
      .post('/todos')
      .send(newTodo)
      .expect(201);

    const response = await supertest(app)
      .delete(`/todos/${newTodo.id}`)
      .expect(200);
    expect(response.body.message).toBe('Todo deleted');
  });

  it('should return 400 for invalid todo creation', async () => {
    await supertest(app)
      .post('/todos')
      .send({})
      .expect(400);

    await supertest(app)
      .post('/todos')
      .send({ title: 'Too Long Title' })
      .expect(400);
  });

  it('should return 404 for non-existent todo', async () => {
    const response = await supertest(app)
      .get(`/todos/1`)
      .expect(404);
    expect(response.body.message).toBe('Todo not found');
  });
});
